-- Recuperada da producao (supabase_migrations.schema_migrations).
--
-- Esta migration JA ESTA APLICADA no banco de producao, mas nao tinha arquivo
-- no repositorio: o check "Supabase Preview" falhava em todo push para a main
-- com "Remote migration versions not found in local migrations directory",
-- e a cadeia local nao reconstruia a producao.
--
-- O SQL abaixo e o que a propria producao registrou ter executado.
-- versao: 20260321130011
-- nome:   salespro_mig_008_bi_chat_supply_quotes_final

-- BI / Chat / Email
CREATE TABLE IF NOT EXISTS public.icp_data (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, client_id UUID NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE UNIQUE, ramo_atividade TEXT, grupo_nicho TEXT, capital_social DECIMAL(15,2), num_colaboradores INTEGER, is_icp_match BOOLEAN DEFAULT false, bitrix_id TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.client_portfolio (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, client_id UUID NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'inactive' CHECK (status IN ('active','inactive')), last_purchase_date DATE, assigned_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), assigned_by UUID REFERENCES public.salespeople(id), source TEXT DEFAULT 'database', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE(client_id, salesperson_id));
CREATE TABLE IF NOT EXISTS public.portfolio_settings (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, setting_key TEXT NOT NULL UNIQUE, setting_value TEXT NOT NULL, description TEXT, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.lead_routing_log (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, client_id UUID REFERENCES public.clients(id) ON DELETE SET NULL, from_salesperson_id UUID REFERENCES public.salespeople(id), to_salesperson_id UUID REFERENCES public.salespeople(id), routing_reason TEXT NOT NULL, notes TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.bitrix24_sync_logs (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, sync_type TEXT NOT NULL DEFAULT 'sync-all', status TEXT NOT NULL DEFAULT 'success', companies_from_bitrix INTEGER DEFAULT 0, companies_to_bitrix INTEGER DEFAULT 0, deals_from_bitrix INTEGER DEFAULT 0, deals_to_bitrix INTEGER DEFAULT 0, error_message TEXT, duration_ms INTEGER, triggered_by TEXT DEFAULT 'manual', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.sdr_alert_history (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), triggered_by TEXT DEFAULT 'cron', sdrs_notified INTEGER NOT NULL DEFAULT 0, threshold_used INTEGER NOT NULL DEFAULT 3, sdr_details JSONB NOT NULL DEFAULT '[]'::jsonb, admin_emails TEXT[] NOT NULL DEFAULT '{}'::text[], consecutive_days_threshold integer NOT NULL DEFAULT 3);
CREATE TABLE IF NOT EXISTS public.email_logs (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, function_name text NOT NULL, recipient_email text NOT NULL, subject text, status text NOT NULL DEFAULT 'sent', error_message text, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.email_tracking_events (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, email_id UUID REFERENCES public.email_logs(id) ON DELETE CASCADE, event_type TEXT NOT NULL CHECK (event_type IN ('sent','delivered','opened','clicked','bounced','failed')), metadata JSONB DEFAULT '{}', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.chat_conversations (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE, title TEXT NOT NULL DEFAULT 'Nova conversa', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.chat_messages (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, conversation_id UUID NOT NULL REFERENCES public.chat_conversations(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('user','assistant')), content TEXT NOT NULL, response_mode TEXT NOT NULL DEFAULT 'text' CHECK (response_mode IN ('text','audio','both')), voice_id TEXT DEFAULT 'CwhRBWXzGAHq8TQ4Fs17', voice_name TEXT DEFAULT 'Roger', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.dashboard_layouts (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, layout_name TEXT NOT NULL DEFAULT 'default', widgets JSONB NOT NULL DEFAULT '[]'::jsonb, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE(user_id, layout_name));
-- Quotes
CREATE TABLE IF NOT EXISTS public.salesperson_preferences (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, salesperson_id UUID NOT NULL REFERENCES public.salespeople(id) ON DELETE CASCADE UNIQUE, sound_enabled BOOLEAN NOT NULL DEFAULT true, sound_volume NUMERIC(3,2) NOT NULL DEFAULT 0.7, celebration_sound TEXT DEFAULT 'default', notification_sound TEXT DEFAULT 'default', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.quotes (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, quote_number TEXT NOT NULL UNIQUE, client_id UUID REFERENCES public.clients(id) ON DELETE SET NULL, salesperson_id UUID REFERENCES public.salespeople(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sent','approved','rejected','expired')), items JSONB NOT NULL DEFAULT '[]'::jsonb, subtotal NUMERIC(12,2) NOT NULL DEFAULT 0, discount_percent NUMERIC(5,2) DEFAULT 0, discount_amount NUMERIC(12,2) DEFAULT 0, total NUMERIC(12,2) NOT NULL DEFAULT 0, client_email TEXT, client_phone TEXT, notes TEXT, valid_until DATE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.quote_sync_logs (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, quote_id UUID REFERENCES public.quotes(id) ON DELETE CASCADE, sync_direction TEXT NOT NULL CHECK (sync_direction IN ('to_bitrix','from_bitrix')), status TEXT NOT NULL DEFAULT 'pending', bitrix_deal_id TEXT, error_message TEXT, payload JSONB DEFAULT '{}', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
-- Supply / Supply extensions
CREATE TABLE IF NOT EXISTS public.supplier_products (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, supplier_id UUID REFERENCES public.suppliers(id) ON DELETE CASCADE, product_id UUID REFERENCES public.products(id) ON DELETE CASCADE, unit_price NUMERIC(12,2) NOT NULL, min_order_quantity INTEGER DEFAULT 1, currency TEXT DEFAULT 'BRL', last_price_update TIMESTAMP WITH TIME ZONE DEFAULT now(), is_preferred BOOLEAN DEFAULT false, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE(supplier_id, product_id));
CREATE TABLE IF NOT EXISTS public.supplier_orders (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, supplier_id UUID REFERENCES public.suppliers(id) ON DELETE CASCADE, order_number TEXT, status TEXT DEFAULT 'pending' CHECK (status IN ('pending','confirmed','shipped','delivered','cancelled')), total_amount NUMERIC(12,2) NOT NULL DEFAULT 0, order_date TIMESTAMP WITH TIME ZONE DEFAULT now(), expected_delivery TIMESTAMP WITH TIME ZONE, actual_delivery TIMESTAMP WITH TIME ZONE, notes TEXT, created_by UUID, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.supplier_order_items (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, order_id UUID REFERENCES public.supplier_orders(id) ON DELETE CASCADE, product_id UUID REFERENCES public.products(id) ON DELETE SET NULL, quantity INTEGER NOT NULL, unit_price NUMERIC(12,2) NOT NULL, total_price NUMERIC(12,2) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.supplier_risk_assessments (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, supplier_id UUID REFERENCES public.suppliers(id) ON DELETE CASCADE, assessment_date DATE NOT NULL DEFAULT CURRENT_DATE, financial_risk NUMERIC(3,2) DEFAULT 0.5, delivery_risk NUMERIC(3,2) DEFAULT 0.5, quality_risk NUMERIC(3,2) DEFAULT 0.5, overall_risk NUMERIC(3,2) DEFAULT 0.5, risk_level TEXT DEFAULT 'medium' CHECK (risk_level IN ('low','medium','high','critical')), factors JSONB DEFAULT '{}', recommendations TEXT, assessed_by UUID, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
-- Remaining
CREATE TABLE IF NOT EXISTS public.push_subscriptions (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, endpoint TEXT NOT NULL, p256dh TEXT NOT NULL, auth TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE(user_id));
CREATE TABLE IF NOT EXISTS public.demand_forecasts (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, product_id UUID REFERENCES public.products(id) ON DELETE CASCADE, forecast_date DATE NOT NULL, predicted_quantity INTEGER NOT NULL DEFAULT 0, predicted_revenue NUMERIC(12,2) NOT NULL DEFAULT 0, confidence_score NUMERIC(5,2) DEFAULT 0.80, factors JSONB DEFAULT '{}', model_version TEXT DEFAULT 'v1', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.inventory_levels (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, product_id UUID REFERENCES public.products(id) ON DELETE CASCADE UNIQUE, current_stock INTEGER NOT NULL DEFAULT 0, min_stock_level INTEGER NOT NULL DEFAULT 10, max_stock_level INTEGER NOT NULL DEFAULT 100, reorder_point INTEGER NOT NULL DEFAULT 20, lead_time_days INTEGER DEFAULT 7, last_restock_date TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.stock_movements (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, product_id UUID REFERENCES public.products(id) ON DELETE CASCADE, movement_type TEXT NOT NULL CHECK (movement_type IN ('in','out','adjustment')), quantity INTEGER NOT NULL, reason TEXT, reference_id UUID, performed_by UUID, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.price_history (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, supplier_product_id UUID REFERENCES public.supplier_products(id) ON DELETE CASCADE, product_id UUID REFERENCES public.products(id) ON DELETE CASCADE, supplier_id UUID REFERENCES public.suppliers(id) ON DELETE CASCADE, old_price NUMERIC NOT NULL, new_price NUMERIC NOT NULL, recorded_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.price_alerts (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, product_id UUID REFERENCES public.products(id) ON DELETE CASCADE, supplier_id UUID REFERENCES public.suppliers(id) ON DELETE CASCADE, alert_type TEXT NOT NULL CHECK (alert_type IN ('price_drop','price_increase','new_best_price')), old_price NUMERIC, new_price NUMERIC NOT NULL, price_change_percent NUMERIC, is_read BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.digital_signatures (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','pending','signed','rejected','expired')), file_url TEXT, created_by UUID REFERENCES public.salespeople(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), expires_at TIMESTAMP WITH TIME ZONE, signed_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE IF NOT EXISTS public.document_signers (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, document_id UUID NOT NULL REFERENCES public.digital_signatures(id) ON DELETE CASCADE, name TEXT NOT NULL, email TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','signed','rejected')), signed_at TIMESTAMP WITH TIME ZONE, sign_order INTEGER DEFAULT 1, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.workflow_rules (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, name TEXT NOT NULL, description TEXT, trigger_event TEXT NOT NULL, conditions JSONB NOT NULL DEFAULT '[]'::jsonb, actions JSONB NOT NULL DEFAULT '[]'::jsonb, is_active BOOLEAN NOT NULL DEFAULT true, execution_count INTEGER NOT NULL DEFAULT 0, last_executed_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
